    //TODO: When Metcash Pricing Engine model is merged back to MEtcash model move this code to class METEcoResProductCategoryTableEventHandler

    /// <summary>
    /// MPJ_12065_RestrictCostchangesOnPOs on 08 Feb 2022 by chaminda
    /// </summary>
    /// <param name="sender"> Get common object </param>
    /// <param name="e"> get event </param>
    [DataEventHandler(tableStr(EcoResProductCategory), DataEventType::Inserted),
     SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void EcoResProductCategory_onInserted(Common sender, DataEventArgs e)
    {
        EcoResProductCategory productCategory = sender as EcoResProductCategory;
        METPriceChangeEventProduct::metProcessTrackChange(InventTable::findByProduct(productCategory.Product));
    }
